### Initialize New Moose Project (TypeScript)

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/getting-started/from-clickhouse.mdx

Initialize a new Moose project for TypeScript development. This command connects to your ClickHouse instance and generates necessary code.

```bash
moose init --template typescript --db-url "clickhouse://user:password@host:port/database"
```

--------------------------------

### Define Materialized View for Initiative Sales

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/guides/applications/performant-dashboards/existing-oltp-db/2-create-materialized-view[@scope=initiative].mdx

Define a materialized view using TypeScript or Python to pre-aggregate order data by date and initiative.

```typescript
import { OlapMaterializedView, OlapTable } from "@514labs/moose-lib";

// Define the source table (from your OLTP DB)
interface OrdersTable {
  id: string;
  customer_id: string;
  amount: number;
  created_at: Date;
}

// Define the materialized view
interface InitiativeSalesView {
  date: Date;
  initiative_id: string;
  total_sales: number;
  order_count: number;
}

export const initiativeSalesView = new OlapMaterializedView<InitiativeSalesView>(
  "initiative_sales",
  {
    source: "orders", // References your OLTP table
    query: `
      SELECT
        toDate(created_at) as date,
        initiative_id,
        sum(amount) as total_sales,
        count(*) as order_count
      FROM orders
      GROUP BY date, initiative_id
    `,
    refresh: "incremental", // Update as new data arrives
  }
);
```

```python
from moose_lib import OlapMaterializedView
from pydantic import BaseModel
from datetime import date

# Define the materialized view
class InitiativeSalesView(BaseModel):
    date: date
    initiative_id: str
    total_sales: float
    order_count: int

initiative_sales_view = OlapMaterializedView[InitiativeSalesView](
    "initiative_sales",
    source="orders",
    query="""
        SELECT
            toDate(created_at) as date,
            initiative_id,
            sum(amount) as total_sales,
            count(*) as order_count
        FROM orders
        GROUP BY date, initiative_id
    """,
    refresh="incremental",
)
```

--------------------------------

### Define ClickHouse Event Model in TypeScript

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/getting-started/existing-app/fastify.mdx

Define a TypeScript interface for your ClickHouse table schema and create an OlapTable instance. Moose will automatically create this table when 'moose dev' is run.

```typescript
import { OlapTable } from "@514labs/moose-lib";

export interface EventModel {
  id: string;
  amount: number;
  event_time: Date;
  status: 'completed' | 'active' | 'inactive';
}

export const Events = new OlapTable<EventModel>("events", {
  orderByFields: ["event_time"],
});
```

--------------------------------

### Initialize shared ClickHouse client

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/getting-started/existing-app/next-js.mdx

Create a helper to manage ClickHouse connections and execute queries within the moose package.

```typescript
import { getMooseClients, Sql, QueryClient } from "@514labs/moose-lib";

async function getClickhouseClient(): Promise<QueryClient> {
  const { client } = await getMooseClients({
    host: process.env.MOOSE_CLICKHOUSE_CONFIG__HOST ?? "localhost",
    port: process.env.MOOSE_CLICKHOUSE_CONFIG__PORT ?? "18123",
    username: process.env.MOOSE_CLICKHOUSE_CONFIG__USER ?? "panda",
    password: process.env.MOOSE_CLICKHOUSE_CONFIG__PASSWORD ?? "pandapass",
    database: process.env.MOOSE_CLICKHOUSE_CONFIG__DB_NAME ?? "local",
    useSSL: (process.env.MOOSE_CLICKHOUSE_CONFIG__USE_SSL ?? "false") === "true",
  });

  return client.query;
}

export async function executeQuery<T>(query: Sql): Promise<T[]> {
  const queryClient = await getClickhouseClient();
  const result = await queryClient.execute(query);
  return result.json();
}
```

--------------------------------

### Initialize Moose Project

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/guides/static-report-generation.mdx

Create a new Moose project using the typescript-empty template and install dependencies.

```bash
moose init sales-reports typescript-empty
cd sales-reports
pnpm install
```

