import { Client } from 'pg';
import axios from 'axios';

// Postgres connection configuration
const pgClient = new Client({
  host: process.env.POSTGRES_HOST || 'localhost',
  port: parseInt(process.env.POSTGRES_PORT || '5432'),
  database: process.env.POSTGRES_DB || 'postgres',
  user: process.env.POSTGRES_USER || 'postgres',
  password: process.env.POSTGRES_PASSWORD || 'postgres',
});

// Moose ingestion endpoint
const MOOSE_INGEST_URL = 'http://localhost:4000/ingest/ProductEvent';

interface RawProductEvent {
  id: string;
  product_id: string;
  event_type: string;
  user_id: string;
  timestamp: Date;
  properties: any;
}

async function extractAndIngestEvents() {
  console.log('🔌 Connecting to Postgres...');
  await pgClient.connect();

  console.log('📊 Extracting events from raw.product_events...');

  try {
    // Query the raw product events
    const query = `
      SELECT
        id,
        product_id,
        event_type,
        user_id,
        timestamp,
        properties
      FROM raw.product_events
      ORDER BY timestamp ASC
    `;

    const result = await pgClient.query<RawProductEvent>(query);
    console.log(`📦 Found ${result.rows.length} events to process`);

    if (result.rows.length === 0) {
      console.log('⚠️  No events found. Creating sample data...');
      await createSampleData();
      return;
    }

    // Process events in batches
    const batchSize = 100;
    let successCount = 0;
    let errorCount = 0;

    for (let i = 0; i < result.rows.length; i += batchSize) {
      const batch = result.rows.slice(i, i + batchSize);

      try {
        // Transform and send batch to Moose
        const transformedEvents = batch.map(event => ({
          id: event.id,
          product_id: event.product_id,
          event_type: event.event_type as "view" | "add_to_cart" | "purchase",
          user_id: event.user_id,
          timestamp: event.timestamp,
          properties: event.properties || {}
        }));

        await axios.post(MOOSE_INGEST_URL, transformedEvents, {
          headers: { 'Content-Type': 'application/json' }
        });

        successCount += batch.length;
        console.log(`✅ Processed batch ${Math.floor(i / batchSize) + 1} (${batch.length} events)`);

        // Small delay to avoid overwhelming the system
        await new Promise(resolve => setTimeout(resolve, 100));

      } catch (error) {
        console.error(`❌ Error processing batch ${Math.floor(i / batchSize) + 1}:`, error);
        errorCount += batch.length;
      }
    }

    console.log(`🎉 Extraction complete! Success: ${successCount}, Errors: ${errorCount}`);

  } catch (error) {
    console.error('❌ Error during extraction:', error);
  } finally {
    await pgClient.end();
  }
}

async function createSampleData() {
  console.log('🔧 Creating sample data in raw.product_events...');

  try {
    // Create schema and table if they don't exist
    await pgClient.query('CREATE SCHEMA IF NOT EXISTS raw');

    await pgClient.query(`
      CREATE TABLE IF NOT EXISTS raw.product_events (
        id TEXT PRIMARY KEY,
        product_id TEXT NOT NULL,
        event_type TEXT NOT NULL,
        user_id TEXT NOT NULL,
        timestamp TIMESTAMP NOT NULL,
        properties JSONB
      )
    `);

    // Generate sample events
    const sampleEvents = [];
    const products = ['prod_001', 'prod_002', 'prod_003', 'prod_004', 'prod_005'];
    const users = ['user_1', 'user_2', 'user_3', 'user_4', 'user_5', 'user_6'];
    const eventTypes = ['view', 'add_to_cart', 'purchase'];

    let eventId = 1;
    const now = new Date();

    // Generate events over the past 7 days
    for (let day = 7; day >= 0; day--) {
      for (let hour = 0; hour < 24; hour++) {
        const eventsThisHour = Math.floor(Math.random() * 20) + 5; // 5-24 events per hour

        for (let i = 0; i < eventsThisHour; i++) {
          const timestamp = new Date(now.getTime() - (day * 24 + (23 - hour)) * 60 * 60 * 1000 + Math.random() * 3600000);
          const product = products[Math.floor(Math.random() * products.length)];
          const user = users[Math.floor(Math.random() * users.length)];

          // Create a realistic funnel - more views than carts than purchases
          let eventType;
          const rand = Math.random();
          if (rand < 0.7) {
            eventType = 'view';
          } else if (rand < 0.9) {
            eventType = 'add_to_cart';
          } else {
            eventType = 'purchase';
          }

          let properties = {};
          if (eventType === 'purchase') {
            properties = {
              price: Math.round((Math.random() * 200 + 10) * 100) / 100, // $10-210
              quantity: Math.floor(Math.random() * 3) + 1
            };
          } else if (eventType === 'add_to_cart') {
            properties = {
              quantity: Math.floor(Math.random() * 3) + 1
            };
          }

          sampleEvents.push({
            id: `event_${eventId++}`,
            product_id: product,
            event_type: eventType,
            user_id: user,
            timestamp,
            properties
          });
        }
      }
    }

    // Insert sample events
    for (const event of sampleEvents) {
      await pgClient.query(`
