import { IngestPipeline, MaterializedView, Api, sql } from "@514labs/moose-lib";

// Product Events Data Model
export interface ProductEvent {
  id: string;
  product_id: string;
  event_type: "view" | "add_to_cart" | "purchase";
  user_id: string;
  timestamp: Date;
  properties: {
    price?: number;
    quantity?: number;
    [key: string]: any;
  };
}

// Ingest pipeline for product events
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["product_id", "timestamp", "event_type"]
  },
  stream: true,
  ingestApi: true,
});

// Aggregated Views

// 1. Top Products View - aggregates purchases with revenue
interface TopProductsView {
  product_id: string;
  purchase_count: number;
  total_revenue: number;
  last_purchase: Date;
}

export const topProductsView = new MaterializedView<TopProductsView>({
  materializedViewName: "TopProductsView",
  targetTable: {
    name: "top_products_view",
    orderByFields: ["purchase_count", "total_revenue"]
  },
  selectStatement: sql.statement`
    SELECT
      product_id,
      count(*) as purchase_count,
      sum(JSONExtractFloat(properties, 'price')) as total_revenue,
      max(timestamp) as last_purchase
    FROM ${ProductEventPipeline.table}
    WHERE event_type = 'purchase'
      AND JSONExtractFloat(properties, 'price') > 0
    GROUP BY product_id
  `,
  selectTables: [ProductEventPipeline.table],
});

// 2. Conversion Funnel View - tracks user journey through funnel
interface ConversionFunnelView {
  date: Date;
  total_views: number;
  total_add_to_carts: number;
  total_purchases: number;
  view_to_cart_rate: number;
  cart_to_purchase_rate: number;
  overall_conversion_rate: number;
}

export const conversionFunnelView = new MaterializedView<ConversionFunnelView>({
  materializedViewName: "ConversionFunnelView",
  targetTable: {
    name: "conversion_funnel_view",
    orderByFields: ["date"]
  },
  selectStatement: sql.statement`
    SELECT
      toDate(timestamp) as date,
      countIf(event_type = 'view') as total_views,
      countIf(event_type = 'add_to_cart') as total_add_to_carts,
      countIf(event_type = 'purchase') as total_purchases,
      if(total_views > 0, total_add_to_carts / total_views, 0) as view_to_cart_rate,
      if(total_add_to_carts > 0, total_purchases / total_add_to_carts, 0) as cart_to_purchase_rate,
      if(total_views > 0, total_purchases / total_views, 0) as overall_conversion_rate
    FROM ${ProductEventPipeline.table}
    GROUP BY toDate(timestamp)
  `,
  selectTables: [ProductEventPipeline.table],
});

// 3. Hourly Activity View - tracks activity by hour
interface HourlyActivityView {
  hour: Date;
  event_type: string;
  event_count: number;
  unique_users: number;
  unique_products: number;
}

export const hourlyActivityView = new MaterializedView<HourlyActivityView>({
  materializedViewName: "HourlyActivityView",
  targetTable: {
    name: "hourly_activity_view",
    orderByFields: ["hour", "event_type"]
  },
  selectStatement: sql.statement`
    SELECT
      toStartOfHour(timestamp) as hour,
      event_type,
      count(*) as event_count,
      uniq(user_id) as unique_users,
      uniq(product_id) as unique_products
    FROM ${ProductEventPipeline.table}
    GROUP BY toStartOfHour(timestamp), event_type
  `,
  selectTables: [ProductEventPipeline.table],
});

// HTTP API Endpoints

// Top Products API
export const topProductsAPI = new Api<{}, TopProductsView[]>(
  "top-products",
  async (params, { client }) => {
    const query = `
      SELECT
        product_id,
        purchase_count,
        total_revenue,
        last_purchase
      FROM top_products_view
      ORDER BY purchase_count DESC, total_revenue DESC
      LIMIT 50
    `;
    const result = await client.query.execute<TopProductsView>(query);
    return result.json();
  }
);

// Conversion Funnel API
export const conversionFunnelAPI = api<ConversionFunnelView[]>({
  route: "/api/funnel",
  method: "GET"
}, async ({ sql }) => {
  const result = await sql`
    SELECT
      date,
      total_views,
      total_add_to_carts,
      total_purchases,
      view_to_cart_rate,
      cart_to_purchase_rate,
      overall_conversion_rate
    FROM conversion_funnel_view
    ORDER BY date DESC
    LIMIT 30
  `;
  return result;
});

// Hourly Activity API
export const hourlyActivityAPI = api<HourlyActivityView[]>({
  route: "/api/hourly",
  method: "GET"
}, async ({ sql }) => {
  const result = await sql`
    SELECT
      hour,
      event_type,
      event_count,
      unique_users,
      unique_products
    FROM hourly_activity_view
    WHERE hour >= now() - INTERVAL 24 HOUR
    ORDER BY hour DESC, event_type
  `;
  return result;
});

