// Demonstration of the data flow from Postgres to Moose to HTTP API
import axios from 'axios';

interface ProductEvent {
  id: string;
  product_id: string;
  event_type: "view" | "add_to_cart" | "purchase";
  user_id: string;
  timestamp: string;
  properties: {
    price?: number;
    quantity?: number;
  };
}

// Sample raw Postgres data (simulating raw.product_events table)
const samplePostgresEvents: ProductEvent[] = [
  {
    id: "evt_001",
    product_id: "prod_001",
    event_type: "view",
    user_id: "user_1",
    timestamp: "2026-04-17T10:00:00Z",
    properties: {}
  },
  {
    id: "evt_002",
    product_id: "prod_001",
    event_type: "add_to_cart",
    user_id: "user_1",
    timestamp: "2026-04-17T10:05:00Z",
    properties: { quantity: 1 }
  },
  {
    id: "evt_003",
    product_id: "prod_001",
    event_type: "purchase",
    user_id: "user_1",
    timestamp: "2026-04-17T10:10:00Z",
    properties: { price: 49.99, quantity: 1 }
  },
  {
    id: "evt_004",
    product_id: "prod_002",
    event_type: "view",
    user_id: "user_2",
    timestamp: "2026-04-17T11:00:00Z",
    properties: {}
  },
  {
    id: "evt_005",
    product_id: "prod_002",
    event_type: "purchase",
    user_id: "user_2",
    timestamp: "2026-04-17T11:15:00Z",
    properties: { price: 79.99, quantity: 2 }
  }
];

async function demonstrateDataFlow() {
  console.log("🔄 Product Analytics Data Flow Demo");
  console.log("=====================================\n");

  // Step 1: Show raw Postgres data
  console.log("📊 Step 1: Raw Postgres Data (raw.product_events)");
  console.log("Sample events that would be extracted from Postgres:");
  samplePostgresEvents.forEach(event => {
    console.log(`  ${event.id}: ${event.event_type} on ${event.product_id} by ${event.user_id}`);
    if (event.properties.price) {
      console.log(`    Revenue: $${event.properties.price}`);
    }
  });

  // Step 2: Show how events would be ingested into Moose
  console.log("\n🔄 Step 2: Moose Ingestion & Processing");
  console.log("Events would be sent to: POST http://localhost:4000/ingest/ProductEvent");
  console.log("Moose would then:");
  console.log("  - Store events in ClickHouse ProductEvent table");
  console.log("  - Update materialized views (top_products, funnel, hourly)");
  console.log("  - Serve aggregated data via HTTP APIs");

  // Step 3: Test the actual API endpoints
  console.log("\n🌐 Step 3: HTTP API Results (Running on port 3000)");
  try {
    // Test top products endpoint
    console.log("\n📈 Top Products by Purchase Count & Revenue:");
    const topProducts = await axios.get('http://localhost:3000/api/top-products');
    topProducts.data.slice(0, 3).forEach((product: any) => {
      console.log(`  ${product.product_id}: ${product.purchase_count} purchases, $${product.total_revenue} revenue`);
    });

    // Test conversion funnel endpoint
    console.log("\n🔀 Conversion Funnel Analytics:");
    const funnel = await axios.get('http://localhost:3000/api/funnel');
    funnel.data.slice(0, 2).forEach((day: any) => {
      console.log(`  ${day.date}: ${day.total_views} views → ${day.total_add_to_carts} carts → ${day.total_purchases} purchases`);
      console.log(`    Overall conversion rate: ${(day.overall_conversion_rate * 100).toFixed(1)}%`);
    });

    // Test hourly activity endpoint
    console.log("\n⏰ Hourly Activity Breakdown:");
    const hourly = await axios.get('http://localhost:3000/api/hourly');
    const recentEvents = hourly.data.filter((h: any) => h.hour === "2026-04-17T20:00:00Z");
    recentEvents.forEach((hour: any) => {
      console.log(`  ${hour.hour} - ${hour.event_type}: ${hour.event_count} events, ${hour.unique_users} users`);
    });

  } catch (error) {
    console.error("❌ Error testing API endpoints:", error);
  }

  console.log("\n✅ Demo Complete!");
  console.log("\nAPI Endpoints Available:");
  console.log("  GET http://localhost:3000/api/top-products");
  console.log("  GET http://localhost:3000/api/funnel");
  console.log("  GET http://localhost:3000/api/hourly");
  console.log("  GET http://localhost:3000/health");
}

// Run demo if called directly
if (require.main === module) {
  demonstrateDataFlow().catch(console.error);
}

export { demonstrateDataFlow, samplePostgresEvents };

